import { props, state } from '../tags'
import App from '../'
import assert from 'assert'
import { equals, parallel } from './'

describe('factory.equals', () => {
  it('should go down path based on props', () => {
    let count = 0
    const rootModule = {
      state: { foo: 'bar' },
      sequences: {
        test: [
          equals(props`foo`),
          {
            bar: [
              () => {
                count++
              },
            ],
            otherwise: [],
          },
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('test')({ foo: 'bar' })
    assert.strictEqual(count, 1)
  })

  it('should go down path based on state', () => {
    let count = 0
    const rootModule = {
      state: { foo: 'bar' },
      sequences: {
        test: [
          equals(state`foo`),
          {
            bar: [
              () => {
                count++
              },
            ],
            otherwise: [],
          },
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('test')()
    assert.strictEqual(count, 1)
  })

  it('should throw on bad argument', (done) => {
    const rootModule = {
      state: { foo: 'bar' },
      sequences: {
        test: [
          equals('foo'),
          {
            bar: [() => {}],
            otherwise: [],
          },
        ],
      },
    }
    const controller = App(rootModule)
    controller.removeListener('error')
    controller.once('error', (error) => {
      assert.ok(error)
      done()
    })
    controller.getSequence('test')()
  })

  it('should execute parallel actions correctly', (done) => {
    const rootModule = {
      state: {
        foo: 'bar',
        results: [],
      },
      sequences: {
        test: [
          equals(state`foo`),
          {
            bar: parallel([
              ({ store }) => {
                return new Promise((resolve) => {
                  setTimeout(() => {
                    store.push('results', 'first')
                    resolve()
                  }, 30)
                })
              },
              ({ store }) => {
                return new Promise((resolve) => {
                  setTimeout(() => {
                    store.push('results', 'second')
                    resolve()
                  }, 10)
                })
              },
            ]),
            otherwise: [],
          },
        ],
      },
    }

    const controller = App(rootModule)
    controller.getSequence('test')()

    setTimeout(() => {
      const resultState = controller.getState('results')
      // In parallel execution, the second (faster) action should finish first
      assert.deepStrictEqual(resultState, ['second', 'first'])
      done()
    }, 37)
  })
})
